pub unsafe extern "C-unwind" fn av1_count_overlappable_neighbors(
    mut cm: *const AV1_COMMON,
    mut xd: *mut MACROBLOCKD,
) {
    let mut mbmi: *mut MB_MODE_INFO = *((*xd).mi).offset(0 as core::ffi::c_int as isize);
    (*mbmi).overlappable_neighbors = 0 as uint8_t;
    if is_motion_variation_allowed_bsize((*mbmi).bsize) == 0 {
        return;
    }
    foreach_overlappable_nb_above(
        cm,
        xd,
        INT_MAX,
        Some(
            increment_int_ptr
                as unsafe extern "C-unwind" fn(
                    *mut MACROBLOCKD,
                    core::ffi::c_int,
                    core::ffi::c_int,
                    uint8_t,
                    core::ffi::c_int,
                    *mut MB_MODE_INFO,
                    *mut core::ffi::c_void,
                    core::ffi::c_int,
                ) -> (),
        ),
        &raw mut (*mbmi).overlappable_neighbors as *mut uint8_t as *mut core::ffi::c_void,
    );
    if (*mbmi).overlappable_neighbors != 0 {
        return;
    }
    foreach_overlappable_nb_left(
        cm,
        xd,
        INT_MAX,
        Some(
            increment_int_ptr
                as unsafe extern "C-unwind" fn(
                    *mut MACROBLOCKD,
                    core::ffi::c_int,
                    core::ffi::c_int,
                    uint8_t,
                    core::ffi::c_int,
                    *mut MB_MODE_INFO,
                    *mut core::ffi::c_void,
                    core::ffi::c_int,
                ) -> (),
        ),
        &raw mut (*mbmi).overlappable_neighbors as *mut uint8_t as *mut core::ffi::c_void,
    );
}
