#[inline]
unsafe extern "C-unwind" fn build_obmc_inter_pred_above(
    mut xd: *mut MACROBLOCKD,
    mut rel_mi_row: core::ffi::c_int,
    mut rel_mi_col: core::ffi::c_int,
    mut op_mi_size: uint8_t,
    mut dir: core::ffi::c_int,
    mut above_mi: *mut MB_MODE_INFO,
    mut fun_ctxt: *mut core::ffi::c_void,
    num_planes: core::ffi::c_int,
) {
    let mut ctxt: *mut obmc_inter_pred_ctxt = fun_ctxt as *mut obmc_inter_pred_ctxt;
    let bsize: BLOCK_SIZE = (**((*xd).mi).offset(0 as core::ffi::c_int as isize)).bsize;
    let overlap: core::ffi::c_int = (if (block_size_high[bsize as usize]
        as core::ffi::c_int)
        < block_size_high[BLOCK_64X64 as core::ffi::c_int as usize] as core::ffi::c_int
    {
        block_size_high[bsize as usize] as core::ffi::c_int
    } else {
        block_size_high[BLOCK_64X64 as core::ffi::c_int as usize] as core::ffi::c_int
    }) >> 1 as core::ffi::c_int;
    let mut plane: core::ffi::c_int = 0 as core::ffi::c_int;
    while plane < num_planes {
        let mut pd: *const macroblockd_plane = &raw mut *((*xd).plane)
            .as_mut_ptr()
            .offset(plane as isize) as *mut macroblockd_plane;
        let bw: core::ffi::c_int = op_mi_size as core::ffi::c_int * MI_SIZE
            >> (*pd).subsampling_x;
        let bh: core::ffi::c_int = overlap >> (*pd).subsampling_y;
        let plane_col: core::ffi::c_int = rel_mi_col * MI_SIZE >> (*pd).subsampling_x;
        if !(av1_skip_u4x4_pred_in_obmc(bsize, pd, 0 as core::ffi::c_int) != 0) {
            let dst_stride: core::ffi::c_int = (*pd).dst.stride;
            let dst: *mut uint8_t = &raw mut *((*pd).dst.buf).offset(plane_col as isize)
                as *mut uint8_t;
            let tmp_stride: core::ffi::c_int = *((*ctxt).adjacent_stride)
                .offset(plane as isize);
            let tmp: *const uint8_t = &raw mut *(*((*ctxt).adjacent).offset(plane as isize))
                .offset(plane_col as isize) as *mut uint8_t;
            let mask: *const uint8_t = av1_get_obmc_mask(bh) as *const uint8_t;
            let is_hbd: core::ffi::c_int = is_cur_buf_hbd(xd) as core::ffi::c_int;
            if is_hbd != 0 {
                aom_highbd_blend_a64_vmask_c(
                    dst,
                    dst_stride as uint32_t,
                    dst,
                    dst_stride as uint32_t,
                    tmp,
                    tmp_stride as uint32_t,
                    mask,
                    bw,
                    bh,
                    (*xd).bd,
                );
            } else {
                aom_blend_a64_vmask_c(
                    dst,
                    dst_stride as uint32_t,
                    dst,
                    dst_stride as uint32_t,
                    tmp,
                    tmp_stride as uint32_t,
                    mask,
                    bw,
                    bh,
                );
            }
        }
        plane += 1;
    }
}
